const uint8_t *home_icon_1bpp_data(HomeIconId id)
{
    switch (id) {
    case HomeIconId::Clock: return icon_clock_data;
    case HomeIconId::Transfer: return icon_transfer_data;
    case HomeIconId::Images: return icon_images_data;
    case HomeIconId::Files: return icon_files_data;
    case HomeIconId::Book: return icon_book_data;
    case HomeIconId::News: return icon_news_data;
    case HomeIconId::Music: return icon_music_data;
    case HomeIconId::Radio: return icon_radio_data;
    case HomeIconId::Setting: return icon_setting_data;
    case HomeIconId::DeepSeek: return icon_deepseek_data;
    case HomeIconId::WeChatReading: return icon_wechat_reading_data;
    case HomeIconId::ZhiHu: return icon_zhihu_data;
    default: return nullptr;
    }
}
